/**
 * frontend/src/pages/Login.jsx - PAGE DE CONNEXION
 * ✅ Login/Register en tabs
 * ✅ JWT authentication
 * ✅ Validation formulaires
 */

import React, { useState } from 'react';
import authService from './auth_service';

const COLORS = {
  primary: '#4F46E5',
  danger: '#EF4444',
  success: '#10B981',
  textMain: '#1E293B',
  textMuted: '#64748B',
  border: '#E2E8F0',
  background: '#F8FAFC'
};

const Login = ({ onLoginSuccess }) => {
  const [isRegister, setIsRegister] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // Login form
  const [loginData, setLoginData] = useState({
    username: '',
    password: ''
  });

  // Register form
  const [registerData, setRegisterData] = useState({
    username: '',
    email: '',
    password: '',
    passwordConfirm: '',
    firstName: ''
  });

  /**
   * ✅ HANDLE LOGIN
   */
  const handleLogin = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    const result = await authService.login(
      loginData.username,
      loginData.password
    );

    if (result.success) {
      onLoginSuccess(result.user);
    } else {
      setError(result.error);
    }

    setLoading(false);
  };

  /**
   * ✅ HANDLE REGISTER
   */
  const handleRegister = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    // Validation
    if (registerData.password !== registerData.passwordConfirm) {
      setError('❌ Les mots de passe ne correspondent pas');
      setLoading(false);
      return;
    }

    if (registerData.password.length < 8) {
      setError('❌ Le mot de passe doit contenir au moins 8 caractères');
      setLoading(false);
      return;
    }

    const result = await authService.register(
      registerData.username,
      registerData.email,
      registerData.password,
      registerData.passwordConfirm,
      registerData.firstName
    );

    if (result.success) {
      onLoginSuccess(result.user);
    } else {
      setError(result.error);
    }

    setLoading(false);
  };

  /**
   * ✅ HANDLE TAB SWITCH
   */
  const handleSwitchTab = () => {
    setIsRegister(!isRegister);
    setError(null);
    setLoginData({ username: '', password: '' });
    setRegisterData({ username: '', email: '', password: '', passwordConfirm: '', firstName: '' });
  };

  return (
    <div style={styles.container}>
      <div style={styles.background} />

      <div style={styles.formContainer}>
        <div style={styles.card}>
          {/* Logo */}
          <div style={styles.logo}>
            <div style={styles.logoIcon}>Σ</div>
            <h1 style={styles.logoText}>Attendance OS</h1>
          </div>

          {/* Tabs */}
          <div style={styles.tabs}>
            <button
              style={{
                ...styles.tab,
                borderBottom: !isRegister ? `2px solid ${COLORS.primary}` : 'none',
                color: !isRegister ? COLORS.primary : COLORS.textMuted
              }}
              onClick={handleSwitchTab}
              disabled={loading}
            >
              Connexion
            </button>
            <button
              style={{
                ...styles.tab,
                borderBottom: isRegister ? `2px solid ${COLORS.primary}` : 'none',
                color: isRegister ? COLORS.primary : COLORS.textMuted
              }}
              onClick={handleSwitchTab}
              disabled={loading}
            >
              Inscription
            </button>
          </div>

          {/* Error Message */}
          {error && (
            <div style={styles.errorBox}>
              <span style={styles.errorIcon}>⚠️</span>
              <span>{error}</span>
            </div>
          )}

          {/* LOGIN FORM */}
          {!isRegister ? (
            <form onSubmit={handleLogin} style={styles.form}>
              <div style={styles.formGroup}>
                <label style={styles.label}>Nom d'utilisateur</label>
                <input
                  type="text"
                  value={loginData.username}
                  onChange={(e) =>
                    setLoginData({ ...loginData, username: e.target.value })
                  }
                  placeholder="Entrez votre nom d'utilisateur"
                  style={styles.input}
                  disabled={loading}
                  required
                />
              </div>

              <div style={styles.formGroup}>
                <label style={styles.label}>Mot de passe</label>
                <input
                  type="password"
                  value={loginData.password}
                  onChange={(e) =>
                    setLoginData({ ...loginData, password: e.target.value })
                  }
                  placeholder="Entrez votre mot de passe"
                  style={styles.input}
                  disabled={loading}
                  required
                />
              </div>

              <button
                type="submit"
                style={{
                  ...styles.submitBtn,
                  opacity: loading ? 0.6 : 1,
                  cursor: loading ? 'not-allowed' : 'pointer'
                }}
                disabled={loading}
              >
                {loading ? '⏳ Connexion...' : '🚀 Se connecter'}
              </button>
            </form>
          ) : (
            /* REGISTER FORM */
            <form onSubmit={handleRegister} style={styles.form}>
              <div style={styles.formGroup}>
                <label style={styles.label}>Nom d'utilisateur</label>
                <input
                  type="text"
                  value={registerData.username}
                  onChange={(e) =>
                    setRegisterData({ ...registerData, username: e.target.value })
                  }
                  placeholder="Choisissez un nom d'utilisateur"
                  style={styles.input}
                  disabled={loading}
                  required
                />
              </div>

              <div style={styles.formGroup}>
                <label style={styles.label}>Prénom</label>
                <input
                  type="text"
                  value={registerData.firstName}
                  onChange={(e) =>
                    setRegisterData({ ...registerData, firstName: e.target.value })
                  }
                  placeholder="Votre prénom"
                  style={styles.input}
                  disabled={loading}
                />
              </div>

              <div style={styles.formGroup}>
                <label style={styles.label}>Email</label>
                <input
                  type="email"
                  value={registerData.email}
                  onChange={(e) =>
                    setRegisterData({ ...registerData, email: e.target.value })
                  }
                  placeholder="votre@email.com"
                  style={styles.input}
                  disabled={loading}
                  required
                />
              </div>

              <div style={styles.formGroup}>
                <label style={styles.label}>Mot de passe</label>
                <input
                  type="password"
                  value={registerData.password}
                  onChange={(e) =>
                    setRegisterData({ ...registerData, password: e.target.value })
                  }
                  placeholder="Min. 8 caractères"
                  style={styles.input}
                  disabled={loading}
                  required
                />
              </div>

              <div style={styles.formGroup}>
                <label style={styles.label}>Confirmer le mot de passe</label>
                <input
                  type="password"
                  value={registerData.passwordConfirm}
                  onChange={(e) =>
                    setRegisterData({
                      ...registerData,
                      passwordConfirm: e.target.value
                    })
                  }
                  placeholder="Répétez le mot de passe"
                  style={styles.input}
                  disabled={loading}
                  required
                />
              </div>

              <button
                type="submit"
                style={{
                  ...styles.submitBtn,
                  opacity: loading ? 0.6 : 1,
                  cursor: loading ? 'not-allowed' : 'pointer'
                }}
                disabled={loading}
              >
                {loading ? '⏳ Inscription...' : '✨ S\'inscrire'}
              </button>
            </form>
          )}

          {/* Footer */}
          <p style={styles.footer}>
            {isRegister
              ? 'Vous avez déjà un compte? '
              : 'Pas de compte? '}
            <button
              style={styles.linkBtn}
              onClick={handleSwitchTab}
              disabled={loading}
            >
              {isRegister ? 'Connectez-vous' : 'Inscrivez-vous'}
            </button>
          </p>
        </div>
      </div>
    </div>
  );
};

